-- Biochemistry Ch2: Enzymes — BATCH 4 FINAL (Reversible Inhibition, Irreversible Inhibition, Enzyme Regulation)
-- discipline=biochemistry, foundation=1A. Safe to re-run: deletes only this batch's subtopics, then re-inserts.

DELETE FROM questions WHERE topic = 'Enzymes' AND subtopic IN ('Reversible Inhibition (Competitive, Noncompetitive, Uncompetitive, Mixed)', 'Irreversible Inhibition', 'Enzyme Regulation (Allosteric, Feedback, Covalent Modification, Zymogens)');

-- Q1 [Reversible Inhibition (Competitive, Noncompetitive, Uncompetitive, Mixed)] easy skill1 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Enzymes', 'Reversible Inhibition (Competitive, Noncompetitive, Uncompetitive, Mixed)', 'A researcher studying an enzyme observes that a small molecule slows the reaction, and that adding excess substrate fully restores the original velocity. Given that this molecule and the substrate appear to bind the enzyme in a mutually exclusive fashion, where does this competitive inhibitor most likely bind?', '[{"label": "A", "text": "The active site, directly competing with substrate for it"}, {"label": "B", "text": "An allosteric site distinct from the active site"}, {"label": "C", "text": "Only the enzyme-substrate complex, after substrate binds"}, {"label": "D", "text": "The substrate molecule itself, sequestering it from the enzyme"}]'::jsonb, 'A', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is A because a competitive inhibitor binds the enzyme''s active site, the same site the substrate uses. The textbook states that ''Reversible Competitive inhibition occurs when substrate (S) and inhibitor (I) both bind to the same site on the enzyme. In effect, they compete for the active site and bind in a mutually exclusive fashion'' (line 27809-27810), and it directs the reader to ''describe how substrate and inhibitor bind mutually exclusively to the active site'' (line 27750). Because the inhibitor and substrate share the active site, raising substrate concentration to infinity converts all enzyme to ES so that ''VM is not changed'' while the apparent KM increases (line 27830-27832), which is why adding excess substrate relieves the inhibition. (Choice A) is correct: a competitive inhibitor occupies the active site and competes with substrate for that site, exactly as the source describes (line 27809-27810). (Choice B) is wrong: binding an allosteric site distinct from the active site describes noncompetitive-type inhibition, in which the inhibitor ''does not enter into the pocket where the substrate ... binds'' (line 28356) and binds a separate allosteric site (line 21315), leaving KM unchanged rather than competing for the active site. (Choice C) is wrong: binding only the enzyme-substrate complex describes uncompetitive inhibition, where ''I binds only to ES and not free E'' (line 28099), which lowers both VM and KM and is not relieved by excess substrate. (Choice D) is wrong: a competitive inhibitor binds the enzyme''s active site and competes with the substrate for that site (line 27809-27810); it does not bind or sequester the substrate molecule itself. This is a Knowledge of Scientific Concepts and Principles question because you must recall that competitive inhibitors bind the enzyme''s active site in direct competition with substrate.', 'easy', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 1, 45)
  RETURNING id
)
