-- Q2 [Reversible Inhibition (Competitive, Noncompetitive, Uncompetitive, Mixed)] easy skill1 ans=B
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Enzymes', 'Reversible Inhibition (Competitive, Noncompetitive, Uncompetitive, Mixed)', 'A pharmacologist is characterizing a small molecule that slows an enzyme by binding reversibly to the same active site as the substrate, so the two bind in a mutually exclusive fashion. If she wants to relieve this competitive inhibition in her in vitro assay, which change to the reaction conditions would most effectively restore the enzyme''s activity?', '[{"label": "A", "text": "Adding more of the inhibitor to the reaction"}, {"label": "B", "text": "Increasing the substrate concentration in the reaction"}, {"label": "C", "text": "Nothing, because competitive inhibition cannot be overcome by substrate"}, {"label": "D", "text": "Removing essentially all substrate from the reaction"}]'::jsonb, 'B', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is B because a competitive inhibitor and the substrate bind in a mutually exclusive way to the same active site, so raising the substrate concentration lets substrate outcompete the inhibitor for that site and restores activity. The reference states that competitive inhibition occurs when ''substrate (S) and inhibitor (I) both bind to the same site on the enzyme...they compete for the active site and bind in a mutually exclusive fashion'' (libretexts-biochemistry.txt, lines 27809-27810), and that ''while competitive inhibitors can be overcome by increasing substrate concentration in vitro, uncompetitive inhibitors may exert more pronounced effects in vivo by preventing the accumulation of substrate'' (lines 28564-28566). Consistently, ''With competitive inhibition, the substrate concentration can be raised to meet the requirements of the enzyme'' (lines 28473-28474), and as S rises toward saturation there is ''no free E to which I could bind,'' so \(V_{max}\) is ultimately reached (lines 27829-27830). (Choice A) is wrong because adding more inhibitor shifts the competition further toward the inhibitor and deepens the inhibition rather than relieving it, since S and I compete for the same site (lines 27809-27810). (Choice B) is correct: increasing \([S]\) lets substrate outcompete the inhibitor for the shared active site, which is precisely why ''competitive inhibitors can be overcome by increasing substrate concentration in vitro'' (lines 28564-28565). (Choice C) is wrong because it flips the defining feature of competitive inhibition; competitive inhibition specifically CAN be overcome by excess substrate (lines 28564-28565), unlike uncompetitive inhibition, which ''can''t'' be relieved this way because ''as more substrate accumulates, the reaction reaches a point where the steady state is lost'' (lines 28474-28475). (Choice D) is wrong because removing substrate does the opposite of what is needed; with little substrate the inhibitor faces almost no competition for the active site, whereas relief requires raising \([S]\) so substrate can outcompete the inhibitor (lines 28473-28474). This is a Knowledge of Scientific Concepts and Principles question because you must recall that competitive inhibitors bind the active site reversibly and mutually exclusively with substrate, and can therefore be overcome by increasing the substrate concentration.', 'easy', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 1, 45)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'reversed_relationship', NULL FROM q
