-- Q6 [Reversible Inhibition (Competitive, Noncompetitive, Uncompetitive, Mixed)] medium skill1 ans=B
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Enzymes', 'Reversible Inhibition (Competitive, Noncompetitive, Uncompetitive, Mixed)', 'A pharmacologist studies a small molecule that binds with equal affinity to a metabolic enzyme whether or not its substrate is already bound, forming a catalytically dead complex. As inhibitor is added at several fixed concentrations and substrate is varied, which change in the apparent kinetic parameters would most likely be observed?', '[{"label": "A", "text": "\\(V_{max}\\) is unchanged while the apparent \\(K_m\\) increases."}, {"label": "B", "text": "\\(V_{max}\\) decreases while the apparent \\(K_m\\) is unchanged."}, {"label": "C", "text": "\\(V_{max}\\) decreases and the apparent \\(K_m\\) decreases."}, {"label": "D", "text": "\\(V_{max}\\) is unchanged and the apparent \\(K_m\\) is unchanged."}]'::jsonb, 'B', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is B because the described inhibitor binds both free enzyme and the enzyme-substrate complex with equal affinity, which is the definition of pure noncompetitive inhibition; the source states that ''noncompetitive inhibition occurs when I binds to both E and ES'' and that for this case ''In pure noncompetitive inhibition, VM decreases without changing KM'' (lines 28225, 28554). Because the inhibitor pulls some enzyme into a dead-end ESI complex even at infinite substrate, the apparent \(V_{max}\) falls; because it binds E and ES with the same affinity, it does not perturb the E + S equilibrium, so ''the apparent Km, Kmapp, will not change'' (line 28242). (Choice A) is the signature of competitive inhibition, where the source notes ''VM remains unchanged, the apparent KM increases'' because substrate and inhibitor ''compete for the same active site'' (lines 28546-28547), not the equal-affinity dual binding described here. (Choice B) is correct: \(V_{max}\) decreases while \(K_m\) is unchanged, the exact noncompetitive pattern in which ''the Km is unchanged, and Vm decreases'' (line 28254). (Choice C) describes uncompetitive inhibition, where the inhibitor ''binds only to ES and not free E'' and ''both Vm and Km decrease'' proportionally (lines 28099, 28121-28122); the stem''s inhibitor binds free E as well, so \(K_m\) is not lowered. (Choice D) would describe no functional inhibition at all, which contradicts the formation of a catalytically dead complex that lowers \(V_{max}\) (line 28241). This is a Knowledge of Scientific Concepts and Principles question because you must recall the defining kinetic signature of noncompetitive inhibition and distinguish it from competitive and uncompetitive patterns.', 'medium', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 1, 75)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'adjacent_fact', NULL FROM q
