-- Q21 [Enzyme Regulation (Allosteric, Feedback, Covalent Modification, Zymogens)] medium skill1 ans=C
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds)
  VALUES ('bio_biochem', 'Enzymes', 'Enzyme Regulation (Allosteric, Feedback, Covalent Modification, Zymogens)', 'A researcher studying a linear biosynthetic pathway observes that as substrate flows through the early steps, a metabolite generated upstream binds an enzyme catalyzing a later step and increases its activity, priming the pathway to handle the incoming flux. This pattern is described as feed-forward regulation. Which of the following best characterizes how feed-forward regulation acts on the pathway?', '[{"label": "A", "text": "The final end product of the pathway binds and inhibits the first committed enzyme"}, {"label": "B", "text": "The pathway''s own end product accelerates the enzyme that catalyzes its own formation"}, {"label": "C", "text": "An upstream intermediate regulates the activity of an enzyme acting downstream of it"}, {"label": "D", "text": "An external signal molecule from outside the pathway sets the activity of every enzyme"}]'::jsonb, 'C', 'This is a Biochemistry question that falls under the content category ''Structure and Function of Proteins and Their Constituent Amino Acids.'' The answer is C because feed-forward regulation is the mechanistic opposite of feedback: the textbook groups these as two common allosteric control loops, describing ''feedback inhibition from downstream products or feedforward from upstream substrates'' (line 31126). In feed-forward, a metabolite generated earlier in the pathway (an upstream substrate/intermediate) binds and modulates an enzyme that catalyzes a later, downstream step, so activity flows in the same direction as the pathway rather than backward from the end product. This lets the cell pre-emptively adjust a downstream enzyme in anticipation of substrate that is already on its way through the pathway. (Choice A) is incorrect: an end product binding and inhibiting the first committed enzyme is the definition of feedback inhibition, not feed-forward — the textbook cites serine, ''the end product of the pathway,'' inhibiting the first reaction as ''a classic example of feedback inhibition of the first reaction of a pathway by the end product'' (line 31144), which acts in the opposite direction. (Choice B) is incorrect: a product accelerating the enzyme that makes it describes product-driven autocatalysis, but feed-forward signals originate from ''upstream substrates,'' not from the pathway''s own end product (line 31126). (Choice C) is correct: feed-forward regulation has an upstream intermediate regulate the activity of a downstream enzyme, the direction opposite to feedback, consistent with ''feedforward from upstream substrates'' (line 31126). (Choice D) is incorrect: an external signal setting enzyme activity describes a cell responding to ''external signals'' (line 968), which is a separate regulatory category; feed-forward regulation is an internal pathway loop driven by an upstream intermediate, not an outside molecule. This is a Knowledge of Scientific Concepts and Principles question because you must recall that feed-forward regulation is defined by an upstream pathway intermediate regulating a downstream enzyme, the directional opposite of end-product feedback inhibition.', 'medium', '1A', 'Structure and Function of Proteins and Their Constituent Amino Acids', 'biochemistry', 1, 75)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'reversed_relationship', NULL FROM q
